  display: inline-flex;
}
.column-filter .Select {
  min-width: 11em;
  max-width: 11em;
}
.column-filter .Select__control {
  height: auto;
}
.column-filter .Select__value-container {
  overflow: visible;
  display: block;
  padding: 0;
}
.column-filter .Select__indicator {
  padding: 0 5px 0 0;
}
.column-filter .Select__control--is-disabled {
  background-color: rgba(128, 128, 128, 0.3);
}
.column-filter span.bp6-popover-wrapper,
.column-filter div.bp6-input-group {
  width: 5.7em;
  padding: 0;
}

.column-filter input.bp6-input {
  height: 20px;
  line-height: 20px;
  font-size: 12px;
}

